-- Optional phone number on profiles (signup wizard, docs/DECISIONS.md D-007).
--
-- * Stored in E.164 form (+ and 7 to 15 digits), or null. The signup form passes it in the auth
--   user metadata; the trigger below copies it only if it is well formed, so bad input never fails
--   a sign-in.
-- * Clients cannot change it: the existing column grant on profiles only lets users update
--   full_name. A settings screen can grant update (phone) later.
-- * It is personal data: the Privacy Policy must mention it before launch.
-- Do not edit this file once pushed.

alter table public.profiles
  add column phone text,
  add constraint profiles_phone_format check (phone is null or phone ~ '^\+[1-9][0-9]{6,14}$');

create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_phone text := nullif(new.raw_user_meta_data ->> 'phone', '');
begin
  insert into public.profiles (id, email, full_name, phone)
  values (
    new.id,
    new.email,
    left(nullif(coalesce(new.raw_user_meta_data ->> 'full_name', new.raw_user_meta_data ->> 'name'), ''), 80),
    case when v_phone ~ '^\+[1-9][0-9]{6,14}$' then v_phone else null end
  );
  return new;
end;
$$;

revoke all on function public.handle_new_user() from public, anon, authenticated;
